-- 1. Table: user
CREATE TABLE "user" (
    id_user SERIAL PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    level VARCHAR(20) NOT NULL CHECK (level IN ('Admin', 'Kepala UPT', 'Pemohon', 'Petugas')),
    email_verified SMALLINT NOT NULL DEFAULT 0,
    verification_token VARCHAR(64) DEFAULT NULL,
    foto_profil VARCHAR(255) DEFAULT NULL
);
CREATE INDEX idx_user_verification_token ON "user"(verification_token);

-- 2. Table: petugas
CREATE TABLE petugas (
    id_petugas VARCHAR(30) PRIMARY KEY,
    id_user INTEGER DEFAULT NULL REFERENCES "user"(id_user) ON DELETE SET NULL ON UPDATE SET NULL,
    nama_petugas VARCHAR(100) NOT NULL,
    nip VARCHAR(20) NOT NULL,
    pangkat VARCHAR(60) DEFAULT NULL,
    jabatan VARCHAR(50) NOT NULL,
    foto VARCHAR(255) DEFAULT NULL
);

-- 3. Table: pemohon
CREATE TABLE pemohon (
    id_pemohon VARCHAR(20) PRIMARY KEY,
    id_user INTEGER NOT NULL REFERENCES "user"(id_user) ON DELETE CASCADE ON UPDATE CASCADE,
    nama_pemilik VARCHAR(100) NOT NULL,
    alamat_usaha TEXT NOT NULL,
    jenis_usaha VARCHAR(50) NOT NULL,
    kontak_pemohon VARCHAR(20) DEFAULT NULL
);

-- 4. Table: alat_uttp
CREATE TABLE alat_uttp (
    id_alat SERIAL PRIMARY KEY,
    id_pemohon VARCHAR(20) NOT NULL REFERENCES pemohon(id_pemohon) ON DELETE CASCADE ON UPDATE CASCADE,
    nama_alat VARCHAR(100) NOT NULL,
    merk VARCHAR(50) NOT NULL,
    kapasitas VARCHAR(50) DEFAULT NULL,
    jumlah INTEGER NOT NULL DEFAULT 1,
    tipe_model VARCHAR(50) NOT NULL,
    nomor_seri VARCHAR(50) NOT NULL,
    buatan VARCHAR(50) NOT NULL,
    detail_spesifik TEXT DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_read_admin SMALLINT DEFAULT 0
);
CREATE INDEX idx_alat_uttp_id_pemohon ON alat_uttp(id_pemohon);

-- 5. Table: alat_spbu
CREATE TABLE alat_spbu (
    id_alat INTEGER PRIMARY KEY REFERENCES alat_uttp(id_alat) ON DELETE CASCADE ON UPDATE CASCADE,
    nomor_pulau VARCHAR(10) NOT NULL,
    kecepatan_alir VARCHAR(20) NOT NULL,
    jumlah_nozzle INTEGER NOT NULL,
    daftar_produk_bbm TEXT NOT NULL
);

-- 6. Table: alat_timbangan
CREATE TABLE alat_timbangan (
    id_alat INTEGER PRIMARY KEY REFERENCES alat_uttp(id_alat) ON DELETE CASCADE ON UPDATE CASCADE,
    kapasitas_nominal VARCHAR(50) NOT NULL,
    kelas_ketelitian VARCHAR(20) NOT NULL
);

-- 7. Table: surat_tugas
CREATE TABLE surat_tugas (
    id_surat_tugas SERIAL PRIMARY KEY,
    id_alat INTEGER NOT NULL REFERENCES alat_uttp(id_alat) ON DELETE CASCADE ON UPDATE CASCADE,
    id_petugas VARCHAR(255) NOT NULL,
    no_surat_tugas VARCHAR(100) NOT NULL,
    tgl_tugas DATE NOT NULL,
    status VARCHAR(20) DEFAULT 'Menunggu' CHECK (status IN ('Menunggu', 'Selesai'))
);
CREATE INDEX idx_surat_tugas_id_alat ON surat_tugas(id_alat);

-- 8. Table: cerapan_tera
CREATE TABLE cerapan_tera (
    id_cerapan SERIAL PRIMARY KEY,
    id_surat_tugas INTEGER NOT NULL,
    id_petugas VARCHAR(30) NOT NULL,
    file_cerapan VARCHAR(255) NOT NULL,
    catatan TEXT,
    tgl_upload TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_cerapan_tera_id_surat_tugas ON cerapan_tera(id_surat_tugas);

-- 9. Table: pengujian
CREATE TABLE pengujian (
    id_pengujian SERIAL PRIMARY KEY,
    id_alat INTEGER NOT NULL REFERENCES alat_uttp(id_alat) ON DELETE CASCADE ON UPDATE CASCADE,
    tgl_pengujian DATE NOT NULL,
    metode_uji VARCHAR(100) NOT NULL,
    standar_uji VARCHAR(100) NOT NULL,
    suhu_dasar VARCHAR(20) NOT NULL,
    hasil_uji VARCHAR(20) NOT NULL CHECK (hasil_uji IN ('Sah', 'Batal')),
    status_validasi VARCHAR(20) DEFAULT 'Menunggu' CHECK (status_validasi IN ('Menunggu', 'Tervalidasi'))
);
CREATE INDEX idx_pengujian_id_alat ON pengujian(id_alat);

-- 10. Table: skhp
CREATE TABLE skhp (
    id_skhp SERIAL PRIMARY KEY,
    id_pengujian INTEGER NOT NULL REFERENCES pengujian(id_pengujian) ON DELETE CASCADE ON UPDATE CASCADE,
    id_petugas VARCHAR(30) NOT NULL REFERENCES petugas(id_petugas) ON DELETE CASCADE ON UPDATE CASCADE,
    no_surat VARCHAR(50) NOT NULL UNIQUE,
    nama_kepala_dinas VARCHAR(100) NOT NULL,
    masa_berlaku DATE NOT NULL,
    tgl_terbit DATE NOT NULL,
    no_daftar VARCHAR(50) NOT NULL,
    nip_pejabat VARCHAR(20) NOT NULL
);
CREATE INDEX idx_skhp_id_pengujian ON skhp(id_pengujian);
CREATE INDEX idx_skhp_id_petugas ON skhp(id_petugas);

-- 11. Table: log_aktivitas
CREATE TABLE log_aktivitas (
    id_log SERIAL PRIMARY KEY,
    id_user INTEGER NOT NULL,
    username VARCHAR(50) NOT NULL,
    level VARCHAR(20) NOT NULL,
    aksi VARCHAR(100) NOT NULL DEFAULT 'Login',
    keterangan TEXT,
    ip_address VARCHAR(45) DEFAULT NULL,
    user_agent TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_log_aktivitas_id_user ON log_aktivitas(id_user);
CREATE INDEX idx_log_aktivitas_created_at ON log_aktivitas(created_at);

-- 12. Table: migrations
CREATE TABLE migrations (
    id BIGSERIAL PRIMARY KEY,
    version VARCHAR(255) NOT NULL,
    class VARCHAR(255) NOT NULL,
    group_name VARCHAR(255) NOT NULL,
    namespace VARCHAR(255) NOT NULL,
    time INTEGER NOT NULL,
    batch INTEGER NOT NULL
);

